; blame.asm -- chapter 39: two pairs, C and then boxed alone
; generated by gen39.py
        INCLUDE "msx.inc"
        OUTPUT "blame.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; meet.asm with boxed alone: WHERE IT BREAKS. After a frame whose status says
; C, each pair whose boxes meet stops.
stat    EQU VARS                ; the status the interrupt routine read
ticks   EQU VARS + 1            ; frames, two bytes
names   EQU $C400               ; the copy of the 768 names
copy    EQU $C800               ; the copy of the sprites' attributes
ATT_TABLE EQU $1B00
PAT_TABLE EQU $3800
END_MARK EQU $D0                ; a Y of 208 ends the table
pairs   EQU VARS + 3            ; two pairs, 10 bytes each: X, Y of A and of
                                ; B, the steps of A and of B, moving, the frame
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, END_MARK
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; the shapes: all paper ...
        ld bc, 2048
.shp:   xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .shp
        VRAM_WRITE $0008        ; ... but name 1, the brick
        ld hl, brick
        ld bc, (8 << 8) | VDP_DATA
        otir
        VRAM_WRITE $2000        ; the colours: black on white ...
        ld bc, 2048
.col:   ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .col
        VRAM_WRITE $2008        ; ... but the brick's
        ld hl, brick + 8
        ld bc, (8 << 8) | VDP_DATA
        otir
        VRAM_WRITE PAT_TABLE    ; the sprite patterns
        ld hl, patterns
        ld bc, (96 << 8) | VDP_DATA
        otir
        ld hl, blank            ; the names, into their copy ...
        ld de, names
        ld bc, 768
        ldir
        VRAM_WRITE $1800        ; ... and from there to the VDP
        ld hl, names
        ld bc, 768
.nam:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .nam
        ld hl, 0
        ld (ticks), hl
        ld a, END_MARK          ; no sprites in the copy yet
        ld (copy), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        ld hl, start            ; the two pairs
        ld de, pairs
        ld bc, 20
        ldir
        call build
        in a, (VDP_CTRL)        ; F cleared: the first interrupt ends a frame
        VDP_REG 1, $E2          ; display on, interrupt on, sprites 16 x 16
        ei
main:   halt                    ; the interrupt: the status kept, the copy sent
        ld a, (stat)
        and $20                 ; C: two sprites' pixels met in the last picture
        call nz, tests
        call move
        call build
        jr main

; isr: every frame. The status kept in stat, the copy of the sprites'
; attributes sent (the paper is over: at full speed, chapter 20), the frame
; counted. Keeps AF, BC, HL
isr:    push af
        push bc
        push hl
        in a, (VDP_CTRL)        ; the status: F, 5S and C; the signal down
        ld (stat), a
        VRAM_WRITE ATT_TABLE
        ld hl, copy
        ld bc, (17 << 8) | VDP_DATA
        otir
        ld hl, (ticks)
        inc hl
        ld (ticks), hl
        pop hl
        pop bc
        pop af
        ei
        ret

; tests: each pair still moving asked boxed where it is: WHERE IT BREAKS,
; boxed alone. A pair whose boxes meet stops, and the frame is kept
tests:  ld ix, pairs
        ld a, 2
.pair:  push af
        ld a, (ix+8)            ; moving?
        or a
        jr z, .next
        ld b, (ix+0)
        ld c, (ix+1)            ; B, C: ball A
        ld d, (ix+2)
        ld e, (ix+3)            ; D, E: ball B
        call boxed
        jr nc, .next            ; the boxes are apart
        ld (ix+8), 0            ; the boxes meet: the pair stops
        ld a, (ticks)
        ld (ix+9), a            ; in this frame
.next:  ld de, 10
        add ix, de
        pop af
        dec a
        jr nz, .pair
        ret

; move: each pair still moving, both balls a step on
move:   ld ix, pairs
        ld b, 2
.pair:  ld a, (ix+8)
        or a
        jr z, .next
        ld a, (ix+0)
        add a, (ix+4)
        ld (ix+0), a
        ld a, (ix+1)
        add a, (ix+5)
        ld (ix+1), a
        ld a, (ix+2)
        add a, (ix+6)
        ld (ix+2), a
        ld a, (ix+3)
        add a, (ix+7)
        ld (ix+3), a
.next:  ld de, 10
        add ix, de
        djnz .pair
        ret

; build: the copy of the attributes from the pairs: each ball's Y, X,
; pattern 0, A black and B dark blue
build:  ld ix, pairs
        ld hl, copy
        ld b, 2
.pair:  ld a, (ix+1)
        ld (hl), a
        inc hl
        ld a, (ix+0)
        ld (hl), a
        inc hl
        ld (hl), 0
        inc hl
        ld (hl), BLACK
        inc hl
        ld a, (ix+3)
        ld (hl), a
        inc hl
        ld a, (ix+2)
        ld (hl), a
        inc hl
        ld (hl), 0
        inc hl
        ld (hl), DARK_BLUE
        inc hl
        ld de, 10
        add ix, de
        djnz .pair
        ld (hl), END_MARK
        ret

; boxed: B, C = X, Y of one ball and D, E of the other -> carry if their
; boxes of 16 x 16 share a pixel: X and Y both less than 16 apart. Uses A
boxed:  ld a, d                 ;  5
        sub b                   ;  5  the difference of the X
        add a, 15               ;  8  -15 to 15 become 0 to 30
        cp 31                   ;  8
        ret nc                  ; 12, or 6  16 or more apart
        ld a, e                 ;  5
        sub c                   ;  5  the difference of the Y
        add a, 15               ;  8
        cp 31                   ;  8
        ret                     ; 11  carry: the boxes meet
brick:  db $FF, $80, $80, $80, $FF, $08, $08, $08
        db $14, $14, $14, $14, $14, $14, $14, $14
patterns:                       ; ball 0, face 4, inside of the face 8
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $07, $18, $20, $40, $46, $86, $80, $80
        db $80, $88, $47, $40, $20, $18, $07, $00
        db $E0, $18, $04, $02, $62, $61, $01, $01
        db $01, $11, $E2, $02, $04, $18, $E0, $00
        db $00, $07, $1F, $3F, $39, $79, $7F, $7F
        db $7F, $77, $38, $3F, $1F, $07, $00, $00
        db $00, $E0, $F8, $FC, $9C, $9E, $FE, $FE
        db $FE, $EE, $1C, $FC, $F8, $E0, $00, $00
start:  db 40, 15, 97, 72, 1, 1, 255, 255, 1, 0
        db 40, 127, 93, 127, 1, 0, 255, 0, 1, 0
blank:  ds 768, 0               ; no tiles: every name 0, the paper
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
